/**
 * ConfirmDialog — standardized confirm / destructive / alert prompt.
 *
 * Built on `AppDialog`, so it inherits the shared header, divider style, busy
 * locking and footer spacing. Single source of truth for button order, ARIA
 * attributes and color semantics across every confirmation in the app.
 */
import * as React from 'react';
import { Button, CircularProgress, DialogContentText } from '@mui/material';
import { AppDialog } from './AppDialog';

export type ConfirmTone = 'primary' | 'error' | 'success' | 'warning' | 'info';

export interface ConfirmDialogProps {
    /** Controls visibility. */
    open: boolean;
    /** Called when the user cancels (button, escape or backdrop). Ignored while busy. */
    onCancel: () => void;
    /** Called when the user confirms. */
    onConfirm: () => void;
    /** Dialog title (rendered as the heading). */
    title: React.ReactNode;
    /** Secondary line under the title — e.g. the member being acted on. */
    subtitle?: React.ReactNode;
    /** Body content — either a string or arbitrary nodes. */
    description: React.ReactNode;
    /** Confirm button label. Defaults to "Confirm". */
    confirmLabel?: string;
    /** Cancel button label. Defaults to "Cancel". */
    cancelLabel?: string;
    /** Color tone for the confirm button. Defaults to `primary`. */
    tone?: ConfirmTone;
    /** When true, shows a busy spinner in the confirm button and locks both buttons. */
    busy?: boolean;
    /** Label shown while busy. Defaults to "Working...". */
    busyLabel?: string;
    /** Icon shown on the confirm button when not busy. */
    confirmIcon?: React.ReactNode;
    /** Disables the confirm button without locking the dialog. */
    confirmDisabled?: boolean;
    /** Alert mode — drops the cancel button, leaving a single acknowledge action. */
    hideCancel?: boolean;
    /** Widen beyond the default 'xs' when the body carries form fields. */
    maxWidth?: 'xs' | 'sm' | 'md';
}

export const ConfirmDialog: React.FC<ConfirmDialogProps> = ({
    open,
    onCancel,
    onConfirm,
    title,
    subtitle,
    description,
    confirmLabel = 'Confirm',
    cancelLabel = 'Cancel',
    tone = 'primary',
    busy = false,
    busyLabel = 'Working...',
    confirmIcon,
    confirmDisabled = false,
    hideCancel = false,
    maxWidth = 'xs',
}) => (
    <AppDialog
        open={open}
        onClose={onCancel}
        title={title}
        subtitle={subtitle}
        busy={busy}
        maxWidth={maxWidth}
        aria-labelledby="confirm-dialog-title"
        aria-describedby="confirm-dialog-description"
        actions={
            <>
                {!hideCancel && (
                    <Button onClick={onCancel} color="inherit" disabled={busy}>
                        {cancelLabel}
                    </Button>
                )}
                <Button
                    onClick={onConfirm}
                    color={tone}
                    variant="contained"
                    disabled={busy || confirmDisabled}
                    autoFocus={hideCancel}
                    startIcon={busy ? <CircularProgress size={16} color="inherit" /> : confirmIcon}
                >
                    {busy ? busyLabel : confirmLabel}
                </Button>
            </>
        }
    >
        {typeof description === 'string' ? (
            <DialogContentText id="confirm-dialog-description">{description}</DialogContentText>
        ) : (
            <div id="confirm-dialog-description">{description}</div>
        )}
    </AppDialog>
);

export default ConfirmDialog;
